import math
from numbers import Real

class ComplexNumber:
    def __init__(self, real, imaginary):
        # Store as floats for numerical operations
        self.real = float(real)
        self.imag = float(imag)

    def __eq__(self, other):
        if isinstance(other, ComplexNumber):
            return (math.isclose(self.real, other.real, rel_tol=1e-9, abs_tol=1e-12) and
                    math.isclose(self.imag, other.imag, rel_tol=1e-9, abs_tol=1e-12))
        if isinstance(other, Real):
            return (math.isclose(self.real, float(other), rel_tol=1e-9, abs_tol=1e-12) and
                    math.isclose(self.imag, 0.0, rel_tol=1e-9, abs_tol=1e-12))
        return NotImplemented

    def _coerce_other(self, other):
        if isinstance(other, ComplexNumber):
            return other
        if isinstance(other, Real):
            return ComplexNumber(other, 0.0)
        return None

    def __add__(self, other):
        o = self._coerce_other(other)
        if o is None:
            return NotImplemented
        return ComplexNumber(self.real + o.real, self.imag + o.imag)

    def __radd__(self, other):
        return self.__add__(other)

    def __sub__(self, other):
        o = self._coerce_other(other)
        if o is None:
            return NotImplemented
        return ComplexNumber(self.real - o.real, self.imag - o.imag)

    def __rsub__(self, other):
        o = self._coerce_other(other)
        if o is None:
            return NotImplemented
        return ComplexNumber(o.real - self.real, o.imag - self.imag)

    def __mul__(self, other):
        o = self._coerce_other(other)
        if o is None:
            return NotImplemented
        a, b = self.real, self.imag
        c, d = o.real, o.imag
        return ComplexNumber(a * c - b * d, b * c + a * d)

    def __rmul__(self, other):
        return self.__mul__(other)

    def __truediv__(self, other):
        o = self._coerce_other(other)
        if o is None:
            return NotImplemented
        c, d = o.real, o.imag
        denom = c * c + d * d
        if math.isclose(denom, 0.0, abs_tol=1e-15):
            raise ZeroDivisionError("division by zero complex number")
        a, b = self.real, self.imag
        real_part = (a * c + b * d) / denom
        imag_part = (b * c - a * d) / denom
        return ComplexNumber(real_part, imag_part)

    def __abs__(self):
        # Return the modulus |z|
        return math.hypot(self.real, self.imag)

    def conjugate(self):
        return ComplexNumber(self.real, -self.imag)

    def exp(self):
        # e^(a + b i) = e^a * (cos b + i sin b)
        ea = math.exp(self.real)
        return ComplexNumber(ea * math.cos(self.imag), ea * math.sin(self.imag))

    def __repr__(self):
        return f"ComplexNumber({self.real}, {self.imag})"
